import json

def evaluate_memories(facts, memories, policies, updates):
    # Create a dictionary to store the changes
    changes = {}

    # Iterate over the updates
    for update in updates:
        # Iterate over the memories
        for memory in memories:
            # Check if the memory is affected by the update
            if is_affected(memory, update, facts):
                # Determine the action to take
                action = determine_action(memory, update, facts, policies)
                # Store the action in the changes dictionary
                changes[memory['id']] = action

    # Return the changes dictionary
    return changes


def is_affected(memory, update, facts):
    # Check if the update is older than the fact it concerns
    if update['observed'] < memory['text'].split(' ')[0]:
        return False
    # Check if the memory rests on another memory
    if memory['id'] in [f['id'] for f in facts]:
        return False
    # Check if the update affects the memory
    for fact in facts:
        if fact['id'] == update['id'] and fact['text'] in memory['text']:
            return True
    return False


def determine_action(memory, update, facts, policies):
    # Check if the update is a retraction
    if update['text'].startswith('The following fact has been retracted:'):
        # Check if the fact is still supported
        if any(f['id'] == memory['id'] for f in facts):
            return 'withdraw'
        else:
            return 'keep'
    # Check if the update is a replacement
    elif update['text'].startswith('The following fact has been updated:'):
        # Check if the fact is still supported
        if any(f['id'] == memory['id'] for f in facts):
            return 'recompute'
        else:
            return 'keep'
    # Check if the update is a doubt
    elif update['text'].startswith('The following fact is now in doubt:'):
        # Check if the fact is still supported
        if any(f['id'] == memory['id'] for f in facts):
            return 'uncertain'
        else:
            return 'keep'
    # Check if the update is a new fact
    else:
        # Check if the fact is still supported
        if any(f['id'] == memory['id'] for f in facts):
            return 'recompute'
        else:
            return 'keep'


def main():
    # Load the data
    data = json.loads(open('data.json').read())

    # Evaluate the memories
    changes = evaluate_memories(data['facts'], data['memories'], data['policies'], data['updates'])

    # Print the changes
    print(json.dumps({'changes': changes}, indent=4))


if __name__ == "__main__":
    main()

